/* ЗАДАЧИ ЭЙНШТЕЙНА — логические задачи «кто где живёт» с сеткой «✓ — ✕».
   Генератор: случайное решение → много верных условий → условия добавляются,
   пока решатель не найдёт единственное решение, потом лишние убираются.
   Решатель — сужение возможных домов для каждого признака плюс перебор с возвратом;
   он же даёт подсказку: какое условие сейчас продвигает решение и что из него следует.
   На листе: сетка для пометок (щелчок: пусто → ✕ → ✓), таблица ответа со списками
   и условия для печати. Условия видны и в панели. */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}

const ПАМЯТЬ = 'задача-эйнштейна';
const СТОЯНКА = {r: 1, c: 0};
const R0 = 4, C0 = 2;                         /* тело сетки — с C5 */
const ШИР = 48;                               /* ширина столбца сетки в точках */

/* Категории: метка (в сетке), кто (подлежащее), кем (творительный), кого (родительный), признак, не (отрицание). */
const ИМЕНА = [['Аня', 'Аней', 'Ани'], ['Борис', 'Борисом', 'Бориса'], ['Вика', 'Викой', 'Вики'], ['Глеб', 'Глебом', 'Глеба'],
  ['Дина', 'Диной', 'Дины'], ['Егор', 'Егором', 'Егора'], ['Женя', 'Женей', 'Жени']]
  .map(([м, кем, кого]) => ({метка: м, кто: м, кем, кого}));
const ЦВЕТА = [['красный', 'красного', 'красном'], ['синий', 'синего', 'синем'], ['зелёный', 'зелёного', 'зелёном'], ['жёлтый', 'жёлтого', 'жёлтом'],
  ['белый', 'белого', 'белом'], ['серый', 'серого', 'сером']]
  .map(([м, р, п]) => ({метка: м, кто: 'жилец ' + р + ' дома', кем: 'жильцом ' + р + ' дома', кого: 'жильца ' + р + ' дома', признак: 'живёт в ' + п + ' доме', не: 'живёт не в ' + п + ' доме'}));
const НАПИТКИ = [['чай', 'чая', 'чай'], ['кофе', 'кофе', 'кофе'], ['сок', 'сока', 'сок'], ['молоко', 'молока', 'молоко'], ['какао', 'какао', 'какао'], ['квас', 'кваса', 'квас'], ['воду', 'воды', 'воду']]
  .map(([м, р, в]) => ({метка: м === 'воду' ? 'вода' : м, кто: 'любитель ' + р, кем: 'любителем ' + р, кого: 'любителя ' + р, признак: 'пьёт ' + в, не: 'не пьёт ' + в}));
const ПИТОМЦЫ = [['кот', 'кота', 'кота'], ['пёс', 'пса', 'пса'], ['рыбка', 'рыбки', 'рыбку'], ['хомяк', 'хомяка', 'хомяка'], ['попугай', 'попугая', 'попугая'], ['ёж', 'ежа', 'ежа']]
  .map(([м, р, в]) => ({метка: м, кто: 'хозяин ' + р, кем: 'хозяином ' + р, кого: 'хозяина ' + р, признак: 'держит ' + в, не: 'не держит ' + в}));
const КАТЕГОРИИ = [{имя: 'Имя', пул: ИМЕНА}, {имя: 'Цвет дома', пул: ЦВЕТА}, {имя: 'Напиток', пул: НАПИТКИ}, {имя: 'Питомец', пул: ПИТОМЦЫ}];
const УРОВНИ = {
  'лёгкая — 3 дома':   {N: 3, кат: [0, 1, 3], типы: ['same', 'not', 'next']},
  'средняя — 4 дома':  {N: 4, кат: [0, 1, 2, 3], типы: ['same', 'not', 'next', 'left1']},
  'трудная — 5 домов': {N: 5, кат: [0, 1, 2, 3], типы: ['same', 'not', 'next', 'left1', 'left']},
};

let игра = null, сНачала = 0, тик = null;
const случайно = n => Math.floor(Math.random() * n);
function перемешать(м){ const a = м.slice(); for(let i = a.length - 1; i > 0; i--){ const j = случайно(i + 1); [a[i], a[j]] = [a[j], a[i]]; } return a; }
const бит = n => { let k = 0; while(n){ k += n & 1; n >>= 1; } return k; };
const номерБита = m => 31 - Math.clz32(m);

/* ===== решатель =====
   Сущность e = категория·N + значение; категория 0 — номер дома (значение = дом).
   dom[e] — маска домов, где эта сущность ещё может быть. */
function начальныеДомены(N, K){
  const ВСЕ = (1 << N) - 1, dom = new Array(K * N).fill(ВСЕ);
  for(let v = 0; v < N; v++) dom[v] = 1 << v;
  return dom;
}
function применить(dom, у, N){
  const ВСЕ = (1 << N) - 1, a = у.a, b = у.b;
  const до = dom[a] + dom[b] * 64;
  if(у.тип === 'same'){ const m = dom[a] & dom[b]; dom[a] = m; dom[b] = m; }
  else if(у.тип === 'not'){ if(бит(dom[a]) === 1) dom[b] &= ~dom[a]; if(бит(dom[b]) === 1) dom[a] &= ~dom[b]; }
  else if(у.тип === 'next'){ dom[a] &= ((dom[b] << 1) | (dom[b] >> 1)) & ВСЕ; dom[b] &= ((dom[a] << 1) | (dom[a] >> 1)) & ВСЕ; }
  else if(у.тип === 'left1'){ dom[a] &= dom[b] >> 1; dom[b] &= (dom[a] << 1) & ВСЕ; }
  else if(у.тип === 'left'){
    if(dom[b]) dom[a] &= (1 << номерБита(dom[b])) - 1;
    if(dom[a]){ const низ = номерБита(dom[a] & -dom[a]); dom[b] &= ВСЕ & ~((1 << (низ + 1)) - 1); }
  }
  return до !== dom[a] + dom[b] * 64;
}
/* все разные внутри категории: одиночка вычёркивается у остальных; дом, куда годится один — его */
function разные(dom, N, K){
  let менялось = false;
  for(let c = 1; c < K; c++){
    for(let v = 0; v < N; v++){
      const m = dom[c * N + v];
      if(бит(m) === 1) for(let w = 0; w < N; w++) if(w !== v && (dom[c * N + w] & m)){ dom[c * N + w] &= ~m; менялось = true; }
    }
    for(let p = 0; p < N; p++){
      const кто = []; for(let v = 0; v < N; v++) if(dom[c * N + v] & (1 << p)) кто.push(v);
      if(!кто.length) return null;
      if(кто.length === 1 && dom[c * N + кто[0]] !== 1 << p){ dom[c * N + кто[0]] = 1 << p; менялось = true; }
    }
  }
  return менялось;
}
function сузить(dom, условия, N, K){
  for(let круг = 0; круг < 200; круг++){
    let менялось = false;
    for(const у of условия) if(применить(dom, у, N)) менялось = true;
    const р = разные(dom, N, K);
    if(р === null || dom.some(x => !x)) return false;
    if(р) менялось = true;
    if(!менялось) return true;
  }
  return true;
}
function сколькоРешений(условия, N, K, предел = 2){
  let найдено = 0, решение = null;
  (function вглубь(dom){
    if(найдено >= предел) return;
    if(!сузить(dom, условия, N, K)) return;
    let лучший = -1, мин = 99;
    for(let e = N; e < K * N; e++){ const k = бит(dom[e]); if(k > 1 && k < мин){ мин = k; лучший = e; } }
    if(лучший < 0){ найдено++; решение = dom.slice(); return; }
    for(let m = dom[лучший]; m; m &= m - 1){ const d = dom.slice(); d[лучший] = m & -m; вглубь(d); if(найдено >= предел) return; }
  })(начальныеДомены(N, K));
  return {найдено, решение};
}

/* ===== генератор ===== */
function создать(уровень){
  const ур = УРОВНИ[уровень] || УРОВНИ['средняя — 4 дома'], N = ур.N, K = ур.кат.length + 1;
  for(let попытка = 0; попытка < 30; попытка++){
    /* какие значения берём из пула и где кто живёт */
    const значения = ур.кат.map(k => перемешать(КАТЕГОРИИ[k].пул.map((x, i) => i)).slice(0, N).sort((a, b) => a - b));
    const дом = new Array(K * N);
    for(let v = 0; v < N; v++) дом[v] = v;
    for(let c = 1; c < K; c++){ const п = перемешать([...Array(N).keys()]); for(let v = 0; v < N; v++) дом[c * N + v] = п[v]; }
    const кат = e => Math.floor(e / N);
    const пул = [];
    for(let a = 0; a < K * N; a++) for(let b = a + 1; b < K * N; b++){
      if(кат(a) === 0 && кат(b) === 0) continue;
      const ра = дом[a], рб = дом[b], разн = кат(a) !== кат(b);
      if(разн && ра === рб) пул.push({тип: 'same', a, b, вес: кат(a) === 0 ? 0.35 : 1});
      if(разн && ра !== рб && ур.типы.includes('not')) пул.push({тип: 'not', a, b, вес: 0.55});
      if(кат(a) === 0) continue;                        /* соседство и «левее» — только между людьми и признаками */
      if(Math.abs(ра - рб) === 1 && ур.типы.includes('next')) пул.push({тип: 'next', a, b, вес: 0.9});
      if(ур.типы.includes('left1')){ if(ра + 1 === рб) пул.push({тип: 'left1', a, b, вес: 0.8}); if(рб + 1 === ра) пул.push({тип: 'left1', a: b, b: a, вес: 0.8}); }
      if(ур.типы.includes('left')){ if(ра + 1 < рб) пул.push({тип: 'left', a, b, вес: 0.7}); if(рб + 1 < ра) пул.push({тип: 'left', a: b, b: a, вес: 0.7}); }
    }
    const порядок = пул.map(у => ({у, k: Math.random() * у.вес})).sort((x, y) => y.k - x.k).map(x => x.у);
    const условия = [];
    let единственное = false;
    for(const у of порядок){
      условия.push(у);
      if(сколькоРешений(условия, N, K).найдено === 1){ единственное = true; break; }
    }
    if(!единственное) continue;
    /* лишние условия — убираем */
    for(const у of перемешать(условия.slice())){
      const без = условия.filter(x => x !== у);
      if(сколькоРешений(без, N, K).найдено === 1) условия.splice(условия.indexOf(у), 1);
    }
    /* порядок в списке: вперемешку, но прямые «живёт в доме №» — не первыми */
    const список = перемешать(условия).sort((x, y) => (x.тип === 'same' && кат(x.a) === 0 ? 1 : 0) - (y.тип === 'same' && кат(y.a) === 0 ? 1 : 0));
    return {N, K, кат: ур.кат, значения, дом, условия: список};
  }
  return null;
}

/* ===== слова ===== */
function значение(e){
  const N = игра.N, c = Math.floor(e / N), v = e % N;
  if(c === 0) return {метка: String(v + 1), кто: 'жилец дома № ' + (v + 1), кем: 'жильцом дома № ' + (v + 1), кого: 'жильца дома № ' + (v + 1), признак: 'живёт в доме № ' + (v + 1), не: 'живёт не в доме № ' + (v + 1)};
  return КАТЕГОРИИ[игра.кат[c - 1]].пул[игра.значения[c - 1][v]];
}
const имяКатегории = c => c === 0 ? 'Дом' : КАТЕГОРИИ[игра.кат[c - 1]].имя;
const Заглавная = s => s.charAt(0).toUpperCase() + s.slice(1);
/* Кто подлежащее: лучше имя; номер дома — всегда в сказуемом. */
function порядокСлов(a, b){
  const N = игра.N, ка = Math.floor(a / N), кб = Math.floor(b / N);
  const имяА = ка > 0 && игра.кат[ка - 1] === 0, имяБ = кб > 0 && игра.кат[кб - 1] === 0;
  return ка === 0 || (имяБ && !имяА) ? [b, a] : [a, b];
}
function фраза(у){
  let a = у.a, b = у.b;
  if(у.тип === 'same' || у.тип === 'not' || у.тип === 'next') [a, b] = порядокСлов(a, b);
  const X = значение(a), Y = значение(b);
  if(у.тип === 'same') return Заглавная(X.кто) + ' ' + Y.признак + '.';
  if(у.тип === 'not') return Заглавная(X.кто) + ' ' + Y.не + '.';
  if(у.тип === 'next') return Заглавная(X.кто) + ' живёт рядом с ' + Y.кем + '.';
  if(у.тип === 'left1') return Заглавная(X.кто) + ' живёт сразу слева от ' + Y.кого + '.';
  return Заглавная(X.кто) + ' живёт левее, чем ' + Y.кто + '.';
}
function вступление(){
  const N = игра.N, имена = игра.кат.map(k => КАТЕГОРИИ[k].имя.toLowerCase());
  return 'На улице в ряд стоят ' + число(N, 'дом', 'дома', 'домов') + ', они пронумерованы слева направо от 1 до ' + N + '. В каждом живёт один человек. '
    + 'У всех разные ' + имена.map(x => x === 'имя' ? 'имена' : x === 'цвет дома' ? 'цвета домов' : x === 'напиток' ? 'любимые напитки' : 'питомцы').join(', ') + '. '
    + 'Кто где живёт? Заполните таблицу ответа.';
}

/* ===== раскладка сетки ===== */
const КАТ_СТОЛБЦОВ = () => [...Array(игра.K - 1).keys()].map(i => i + 1);                     /* 1 … K−1 */
const КАТ_СТРОК = () => [0].concat([...Array(игра.K - 2).keys()].map(i => игра.K - 1 - i));    /* 0, K−1, … 2 */
function блоки(){
  const out = [], было = new Set();
  КАТ_СТРОК().forEach((cr, ri) => КАТ_СТОЛБЦОВ().forEach((cc, ci) => {
    if(cr === cc) return; const ключ = Math.min(cr, cc) + ',' + Math.max(cr, cc);
    if(было.has(ключ)) return; было.add(ключ); out.push({ri, ci, cr, cc});
  }));
  return out;
}
const НИЗ_СЕТКИ = () => R0 + (игра.K - 1) * игра.N - 1;
const ПРАВО_СЕТКИ = () => C0 + (игра.K - 1) * игра.N - 1;
const ОТВЕТ_R = () => НИЗ_СЕТКИ() + 2;                 /* заголовок таблицы ответа; дома — строкой ниже */
/* клетка листа → пара сущностей (или null) */
function параПо(r, c){
  const N = игра.N, ri = Math.floor((r - R0) / N), ci = Math.floor((c - C0) / N);
  if(r < R0 || c < C0 || r > НИЗ_СЕТКИ() || c > ПРАВО_СЕТКИ()) return null;
  const б = блоки().find(x => x.ri === ri && x.ci === ci);
  if(!б) return null;
  const e1 = б.cr * N + (r - R0) % N, e2 = б.cc * N + (c - C0) % N;
  return {a: Math.min(e1, e2), b: Math.max(e1, e2), блок: б};
}
function клеткаПары(a, b){
  const N = игра.N, ка = Math.floor(a / N), кб = Math.floor(b / N);
  const б = блоки().find(x => (x.cr === ка && x.cc === кб) || (x.cr === кб && x.cc === ка));
  const [er, ec] = б.cr === ка ? [a, b] : [b, a];
  return {r: R0 + б.ri * N + er % N, c: C0 + б.ci * N + ec % N};
}
const ключ = (a, b) => Math.min(a, b) + ',' + Math.max(a, b);
function конфликт(a, b){
  /* ✓ конфликтует, если в той же строке или столбце блока есть ещё ✓ */
  if(игра.отметки[ключ(a, b)] !== 2) return false;
  const N = игра.N, ка = Math.floor(a / N), кб = Math.floor(b / N);
  for(let v = 0; v < N; v++){
    const a2 = ка * N + v, b2 = кб * N + v;
    if(a2 !== a && игра.отметки[ключ(a2, b)] === 2) return true;
    if(b2 !== b && игра.отметки[ключ(a, b2)] === 2) return true;
  }
  return false;
}
function рисоватьОтметку(a, b, ошибка){
  const {r, c} = клеткаПары(a, b), к = клетка(r, c), v = игра.отметки[ключ(a, b)] || 0;
  к.значение = v === 2 ? '✓' : v === 1 ? '✕' : '';
