/* ===== ходы в сетке ===== */
function отметить(a, b, v){
  const N = игра.N, изм = [[a, b]];
  if(v) игра.отметки[ключ(a, b)] = v; else delete игра.отметки[ключ(a, b)];
  if(v === 2 && параметры({}).авто !== false){
    const ка = Math.floor(a / N), кб = Math.floor(b / N);
    for(let w = 0; w < N; w++){
      const a2 = ка * N + w, b2 = кб * N + w;
      if(a2 !== a && !игра.отметки[ключ(a2, b)]){ игра.отметки[ключ(a2, b)] = 1; изм.push([a2, b]); }
      if(b2 !== b && !игра.отметки[ключ(a, b2)]){ игра.отметки[ключ(a, b2)] = 1; изм.push([a, b2]); }
    }
  }
  /* перерисовать строку и столбец блока — там могли появиться или уйти конфликты */
  const ка = Math.floor(a / N), кб = Math.floor(b / N);
  for(let w = 0; w < N; w++){ изм.push([ка * N + w, b]); изм.push([a, кб * N + w]); }
  const было = new Set();
  for(const [x, y] of изм){ const к = ключ(x, y); if(было.has(к)) continue; было.add(к); рисоватьОтметку(Math.min(x, y), Math.max(x, y)); }
}
function Ход(){
  const п = книга.повод;
  if(!игра || игра.конец || !п || !п.адрес || п.лист !== игра.лист || п.клеток > 1) return;
  const пара = параПо(п.строка - 1, п.столбец - 1);
  if(!пара) return;
  const v = игра.отметки[ключ(пара.a, пара.b)] || 0;
  отметить(пара.a, пара.b, (v + 1) % 3);           /* пусто → ✕ → ✓ → пусто */
  сохранить();
  наСтоянку(СТОЯНКА.r, СТОЯНКА.c);
}

