/* ===== подсказка: какое условие сейчас что-то даёт ===== */
function доменыИзОтметок(){
  const N = игра.N, K = игра.K, dom = начальныеДомены(N, K), условия = [];
  for(const [k, v] of Object.entries(игра.отметки)){ const [a, b] = k.split(',').map(Number); условия.push({тип: v === 2 ? 'same' : 'not', a, b}); }
  return {dom, условия};
}
function фактыИз(dom){
  /* пары из сетки, которые следуют из доменов: ✕ — домены не пересекаются, ✓ — обе одиночки в одном доме */
  const N = игра.N, out = [];
  for(const б of блоки()) for(let i = 0; i < N; i++) for(let j = 0; j < N; j++){
    const a = б.cr * N + i, b = б.cc * N + j;
    if(!(dom[a] & dom[b])) out.push({a: Math.min(a, b), b: Math.max(a, b), v: 1});
    else if(бит(dom[a]) === 1 && dom[a] === dom[b]) out.push({a: Math.min(a, b), b: Math.max(a, b), v: 2});
  }
  return out;
}
function Подсказка(){
  if(!игра || игра.конец) return;
  const плохие = неверныеОтметки();
  if(плохие.length){ for(const [a, b] of плохие) рисоватьОтметку(a, b, true); панель.сообщение('Сначала ошибки: неверных пометок ' + плохие.length + ' (красные). Подсказка опирается на верные пометки.'); return; }
  const N = игра.N, K = игра.K, база = доменыИзОтметок();
  сузить(база.dom, база.условия, N, K);
  const известно = new Set(фактыИз(база.dom).map(f => ключ(f.a, f.b) + ':' + f.v));
  const новое = f => !известно.has(ключ(f.a, f.b) + ':' + f.v) && (игра.отметки[ключ(f.a, f.b)] || 0) !== f.v;
  /* сначала — одно условие плюс пометки; потом — все условия вместе */
  for(let n = 0; n < игра.условия.length; n++){
    const dom = база.dom.slice();
    if(!сузить(dom, база.условия.concat([игра.условия[n]]), N, K)) continue;
    const ф = фактыИз(dom).filter(новое).sort((x, y) => y.v - x.v);
    if(ф.length){ сказать(ф[0], 'Условие ' + (n + 1) + ' («' + фраза(игра.условия[n]).replace(/\.$/, '') + '»)'); return; }
  }
  const dom = база.dom.slice();
  сузить(dom, база.условия.concat(игра.условия), N, K);
  const ф = фактыИз(dom).filter(новое).sort((x, y) => y.v - x.v);
  if(ф.length){ сказать(ф[0], 'Несколько условий вместе'); return; }
  /* логика без предположений дальше не идёт — открываем факт из решения */
  for(const б of блоки()) for(let i = 0; i < N; i++) for(let j = 0; j < N; j++){
    const a = б.cr * N + i, b = б.cc * N + j;
    if(игра.дом[a] === игра.дом[b] && игра.отметки[ключ(a, b)] !== 2){ сказать({a: Math.min(a, b), b: Math.max(a, b), v: 2}, 'Дальше нужно предположение. Открываю факт'); return; }
  }
  панель.сообщение('Сетка заполнена — перенесите ответ в таблицу и нажмите «Проверить».');
}
function сказать(f, откуда){
  const [pa, pb] = порядокСлов(f.a, f.b);
  const подлежащее = значение(pa), сказуемое = значение(pb);
  отметить(f.a, f.b, f.v);
  игра.подсказок = (игра.подсказок || 0) + 1;
  сохранить(); показатьСчёт();
  панель.сообщение(откуда + ': ' + Заглавная(подлежащее.кто) + ' ' + (f.v === 2 ? (сказуемое.признак || '— это ' + сказуемое.кто) : (сказуемое.не || '— не ' + сказуемое.кто)) + '. Поставил ' + (f.v === 2 ? '✓' : '✕') + ' в сетке.');
}
async function ПоказатьРешение(){
